'use strict';
const $ = id => document.getElementById(id);
const D = window.YaparoResearch, E = window.YaparoDecision, S = window.YaparoSimulation;
const state = {step:0,unlocked:0,brief:null,cards:[],selected:null,batch:0,history:[],plan:null,stale:true,revision:0,answers:{}};
const money = cents => new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(cents/100);
const percent = (n,t) => t ? (n/t*100).toLocaleString('tr-TR',{maximumFractionDigits:2}) : '0';
function el(tag,text,cls) {const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function btn(text,action,cls='text-button') {const b=el('button',text,cls);b.type='button';b.addEventListener('click',action);return b;}
function label(id) {return $(id).selectedOptions?.[0]?.textContent || $(id).value;}
function fillOptions(id,q,initial) {const s=$(id);s.replaceChildren();D.options.filter(o=>o.questionId===q).forEach(o=>{const n=el('option',o.label);n.value=o.value;s.append(n);});if(initial)s.value=initial;}
fillOptions('communication','S1_Q01','product_service_intro');fillOptions('business','S3_Q02','local_retail');
fillOptions('action','S1_Q04','visit_store');fillOptions('sector','S3_Q03','fashion_beauty_lifestyle');
fillOptions('goal','S3_Q01','store_visits');fillOptions('audience','S3_Q05','local_nearby');
const mq=D.questions.find(q=>q.field==='measurement_readiness');
if(mq)fillOptions('measurement',mq.id,'basic_utm');
else [['basic_utm','Temel UTM / platform sinyali'],['platform_pixel','Platform pikseli'],['pixel_capi_crm','Piksel + CRM'],['none','Henüz hazır değil']].forEach(([v,t])=>{const o=el('option',t);o.value=v;$('measurement').append(o);});
$('brief').value='Sentetik örnek: Kadıköy’deki tasarım butiğimde özgün parçaları tanıtmak ve yakındaki insanları mağazaya davet etmek istiyorum.';
$('audience-description').value='Yakındaki özgün tasarım meraklıları';
$('identity').value='Örnek Butik';
const demoOption=el('option','Dinamik deneyim · hazırlanmış örnek değerler');demoOption.value='interactive';$('fixture').prepend(demoOption);$('fixture').value='interactive';
const readinessBox=el('div'),readinessLabel=el('label','Demo senaryoda hesap hazırlığı');readinessLabel.htmlFor='demo-readiness';const readiness=el('select');readiness.id='demo-readiness';[['core','Standart kanallar hazır varsayılsın'],['all','Partnerler dahil hazır varsayılsın'],['none','Hiçbir hesap hazır değil']].forEach(([v,t])=>{const o=el('option',t);o.value=v;readiness.append(o);});readinessBox.append(readinessLabel,readiness,el('p','Yalnız simülasyon varsayımıdır; hiçbir hesap bağlı veya doğrulanmış değildir.','hint'));$('fixture').after(readinessBox);
const dateParts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));$('start').value=`${dateParts.year}-${dateParts.month}-${dateParts.day}`;
function go(step) {if(step>state.unlocked)return;state.step=step;document.body.classList.toggle('planning-stage',step===2);document.querySelectorAll('.step').forEach((n,i)=>n.hidden=i!==step);document.querySelectorAll('#step-nav button').forEach((n,i)=>{n.disabled=i>state.unlocked;n.classList.toggle('active',i===step);n.classList.toggle('done',i<step);if(i===step)n.setAttribute('aria-current','step');else n.removeAttribute('aria-current');});if(step===3)review();$('main').focus();window.scrollTo(0,0);}
document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>go(+b.dataset.step)));
// Incomplete branch-rule rows are not executable: use each question's showWhen instead.
function branches() {
  const root=$('branch-fields');root.replaceChildren();
  const base={...state.answers,S1_Q01:$('communication').value,S3_Q02:$('business').value};
  const qs=D.questions.filter(q=>q.stage===1 && Object.keys(q.showWhen).length && Object.entries(q.showWhen).every(([key,values])=>Array.isArray(base[key])?values.some(v=>base[key].includes(v)):values.includes(base[key])));
  if(!qs.length)return;
  const detail=el('details',undefined,'optional-details');detail.open=['fundraising','public_issue','sale_promotion'].includes(base.S1_Q01);detail.append(el('summary',`Bu isteğe özel ${qs.length} kısa ayrıntı`));
  const fields=el('div',undefined,'details-inner field-pair');
  qs.forEach(q=>{const box=el('div'),id=`q-${q.id}`;const l=el('label',q.label);l.htmlFor=id;box.append(l);
    const options=D.options.filter(o=>o.questionId===q.id);let input;
    if(options.length && q.type==='single_select'){input=el('select');const blank=el('option','Henüz bilmiyorum');blank.value='';input.append(blank);options.forEach(o=>{const n=el('option',o.label);n.value=o.value;input.append(n);});}
    else {input=el(q.type==='textarea'?'textarea':'input');if(q.type==='number'){input.type='number';input.min='0';}else if(input.tagName==='INPUT')input.type='text';input.maxLength=q.validation.max_chars||600;input.placeholder=['single_select','textarea','number'].includes(q.type)?'Kısa bilgi ekle':'Taslak notu · belge / onay doğrulanmaz';}
    input.id=id;input.value=state.answers[q.id]||'';input.dataset.question=q.id;input.addEventListener('input',()=>{state.answers[q.id]=input.value;invalidate();});box.append(input,el('p',q.help,'hint'));fields.append(box);
  });detail.append(fields,el('p','Bu ayrıntılar içerik notudur. Bilinmeyen cevaplar doğrulanmış sayılmaz; belgeler yüklenmez ve politika kapıları açılmaz.','hint details-hint'));root.append(detail);
}
branches();$('communication').addEventListener('change',branches);$('business').addEventListener('change',branches);
function syncLocks(){document.querySelectorAll('#step-nav button').forEach((n,i)=>n.disabled=i>state.unlocked);}
function invalidate(){state.stale=true;state.unlocked=Math.min(state.unlocked,2);syncLocks();if(state.plan)$('decision-status').textContent='Koşullar değişti. Önce dağılımı yeniden öner; önceki sonuç güncel değil.';}
function briefChanged(){invalidate();state.briefDirty=true;state.unlocked=0;syncLocks();}
$('brief-form').addEventListener('input',briefChanged);$('brief-form').addEventListener('change',briefChanged);
function briefObject(){const visible={};document.querySelectorAll('[data-question]').forEach(n=>visible[n.dataset.question]=n.value);return {communication:$('communication').value,business:$('business').value,action:$('action').value,description:$('brief').value.trim(),audience:$('audience-description').value.trim(),sector:$('sector').value,risk:$('risk').value,identity:$('identity').value.trim(),message:$('message').value.trim(),branch:visible};}
function makeCards(){const previous=state.cards;if(previous.length)state.history.push({cards:structuredClone(previous),selected:state.selected,brief:structuredClone(state.brief)});state.batch++;state.cards=S.cards(state.brief,state.batch).map((c,i)=>c.title===previous[i]?.title?S.cards(state.brief,state.batch+1)[i]:c);state.selected=null;state.unlocked=1;invalidate();renderCards();}
$('brief-form').addEventListener('submit',e=>{e.preventDefault();if($('brief').value.trim().length<10){$('brief').setCustomValidity('En az 10 karakterle neyi tanıttığını anlat.');$('brief').reportValidity();return;}
  const b=briefObject(),changed=JSON.stringify(b)!==JSON.stringify(state.brief);if(changed&&state.cards.length){state.history.push({cards:structuredClone(state.cards),selected:state.selected,brief:structuredClone(state.brief)});state.cards=[];}state.brief=b;state.briefDirty=false;if(changed||!state.cards.length)makeCards();if(!state.goalManual)$('goal').value=({visit_store:'store_visits',visit_website:'traffic',buy_online:'ecommerce_purchase',buy_marketplace:'ecommerce_purchase',message_whatsapp:'calls_messages',call:'calls_messages',fill_form:'lead_generation',book_appointment:'appointment',register_event:'event_registration',download_app:'app_install',apply_job:'job_application',donate:'donation',join_membership:'lead_generation',follow_engage:'engagement',understand:'awareness',remember:'awareness'})[b.action]||'awareness';state.unlocked=Math.max(state.unlocked,1);go(1);
});$('brief').addEventListener('input',()=>$('brief').setCustomValidity(''));
function artwork(card){const art=el('div',undefined,`art art-${['a','b','c'][card.kind]} theme-${card.theme||'product'}`);const illustration=el('div',undefined,'demo-illustration');illustration.innerHTML=S.illustration(card.theme);art.append(illustration);const copy=el('div',undefined,'art-copy');copy.style.left=`${card.x}%`;copy.style.top=`${card.y}%`;copy.style.width=`${90-card.x}%`;copy.append(el('div',card.title,'art-title'),el('p',card.message,'art-message'));art.append(copy,el('span',card.cta,'art-cta'),el('span',state.brief?.identity||'YAPARO · ÖRNEK ÇİZİM','art-brand'));return art;}
function renderCards(){const root=$('concepts');root.replaceChildren();state.cards.forEach(c=>{const article=el('article',undefined,`concept-card ${state.selected===c.id?'selected':''}`);article.append(artwork(c));const info=el('div',undefined,'concept-info');info.append(el('h2',c.angle),el('p',c.message),el('div',`${c.tone} · Statik görsel`,'concept-meta'),el('small',`Kanca: ${c.hook} · CTA: ${c.cta}`));
    const actions=el('div',undefined,'card-actions'),choose=btn(state.selected===c.id?'✓ Seçildi':'Bu yönü seç',()=>{state.selected=c.id;invalidate();state.unlocked=2;renderCards();},'choose');choose.setAttribute('aria-pressed',String(state.selected===c.id));
    actions.append(choose,btn('Düzenle',()=>openEditor(c)),btn('Benzerini gör',()=>{c.edits.push({title:c.title,message:c.message,cta:c.cta,x:c.x,y:c.y,theme:c.theme});Object.assign(c,S.alternative(c,state.brief));c.revision++;invalidate();renderCards();}));
    if(c.edits.length)actions.append(btn('Geri al',()=>{Object.assign(c,c.edits.pop());c.revision++;invalidate();renderCards();}));info.append(actions);article.append(info);root.append(article);});$('content-next').disabled=!state.selected;
  $('creative-context').textContent=`${state.brief.identity||'Bu çalışma'} · ${state.brief.audience} · İstek: ${state.brief.description} · Demo grup ${state.batch}`;
  let back=$('previous-trio');if(!back){back=btn('Önceki üçlü',()=>{const old=state.history.pop();if(old){state.cards=old.cards;state.selected=old.selected;state.brief=old.brief;restoreBrief(old.brief);invalidate();state.unlocked=state.selected?2:1;renderCards();}});back.id='previous-trio';$('regenerate').after(back);}back.hidden=!state.history.length;syncLocks();
}
$('regenerate').addEventListener('click',makeCards);
let editing=null,edited=null;
function openEditor(c){editing=c;edited={...c};for(const [field,key] of [['edit-title','title'],['edit-message','message'],['edit-cta','cta'],['edit-x','x'],['edit-y','y']])$(field).value=c[key];$('editor-preview').replaceChildren(artwork(c));$('editor').showModal();}
for(const [field,key] of [['edit-title','title'],['edit-message','message'],['edit-cta','cta'],['edit-x','x'],['edit-y','y']])$(field).addEventListener('input',()=>{edited[key]=['x','y'].includes(key)?+$(field).value:$(field).value;$('editor-preview').replaceChildren(artwork(edited));});
$('editor-cancel').addEventListener('click',()=>$('editor').close());$('editor-save').addEventListener('click',()=>{if(!edited.title.trim()||!edited.cta.trim())return;editing.edits.push({title:editing.title,message:editing.message,cta:editing.cta,x:editing.x,y:editing.y});Object.assign(editing,edited);editing.revision++;invalidate();renderCards();$('editor').close();});
function inputs(){return {budget:+$('budget').value,days:+$('duration').value,value:+$('order-value').value,margin:+$('margin').value,cpa:+$('cpa').value,capacity:+$('capacity').value,goal:$('goal').value,business:$('business').value,audience:$('audience').value,sector:$('sector').value,risk:$('risk').value,communication:$('communication').value,action:$('action').value,geo:{area:'district_city',radius:'radius_local',country:'nationwide'}[$('geo-mode').value],radius:+$('radius').value,region:$('region').value,start:$('start').value,measurement:$('measurement').value,fixture:$('fixture').value,readiness:$('demo-readiness').value,video:$('video').checked,catalog:$('catalog').checked,tracking:$('tracking').checked};}
function fxName(source){return source==='tcmb'?'TCMB gösterge satış':source==='ecb'?'ECB çapraz referans':'Tarihli araştırma örneği';}
function recommend(){
  if(!$('plan-form').reportValidity())return;
  try{
    const i=inputs();
    state.plan=E.evaluate(i,D,i.fixture==='interactive'?S.forecast(i,D):null,window.YaparoSources?.getFx(sourceContext()));
    state.revision++;state.stale=false;renderPlan();
    const text=state.plan.interactive?'HAZIRLANMIŞ SENARYO: bölge, hedef, süre ve hazırlık için temsili değerler hesaplandı.':state.plan.bound?'27 Ekim 2026 tarihli TEMSİLİ SC01 verisi kullanıldı.':'Bu koşullara bağlı tahmin yok; bütçe önerilmedi.';
    $('decision-status').textContent=`Öneri ${state.revision} · ${text} Para birimi dönüşümü: ${fxName(state.plan.fx.source)} (${state.plan.fx.source_as_of}). Gerçek AI / reklam platformu sorgusu yapılmadı.`;
    if(!window.YaparoSources?.isCurrent(sourceContext()))window.YaparoSources?.contextChanged();
  }catch(err){state.stale=true;$('decision-status').textContent=err.message;}
}
$('recommend').addEventListener('click',recommend);$('content-next').addEventListener('click',()=>{if(!state.selected)return;state.unlocked=2;$('intent-summary').textContent=`${label('business')} · ${label('action')} · ${state.brief.audience}`;go(2);if(!state.plan||state.stale)recommend();});
$('plan-form').addEventListener('input',e=>{if(!e.target.closest('#recommended'))invalidate();});$('plan-form').addEventListener('change',e=>{if(!e.target.closest('#recommended'))invalidate();});
function geoVisibility(){$('radius-field').hidden=$('geo-mode').value!=='radius';$('radius').disabled=$('radius-field').hidden;$('region').required=$('geo-mode').value!=='country';}
$('geo-mode').addEventListener('change',geoVisibility);geoVisibility();
function guide(row){$('guide-title').textContent=row.channel.name;const root=$('guide-body');root.replaceChildren();const pairs=[['Durum',row.amount?'Önerildi':row.owned?'Bütçe dışı aksiyon':row.eligible?'Koşullu / portföy dışında':'Bu koşullarda seçilmedi'],['Neden',row.reasons.map(x=>E.reasonText[x]).join(' · ')||'Anlamlı test ve tavan koşulları karşılandı.'],['Teknik minimum',row.platform===null?'Hesap / para birimi doğrulaması bekliyor':money(row.platform)],['Anlamlı test minimumu',money(row.useful)],['Faydalı tavan',row.cap===null?'Tahmin yok, hesaplanmadı':money(row.cap)],['Tavanın kaynağı','Temsili talep, toplam bütçe ve ortak işletme kapasitesi / marj sınırının en küçüğü'],['Uzman uygunluğu',`${row.score}/100 · başarı olasılığı değildir`],['Tahmin kaynağı / tarihi',`${row.f?.quality||'Yok'} · ${row.f?.updated||'Yok'} · yalnız SC01`],['Bu koşula bağlı mı?',state.plan.bound?'Evet, tarihli sentetik fixture':'Hayır: gerçek tahmin yenilemesi gerekli'],['Satın alma biçimi',row.channel.purchase],['Nerede işe yarar?',row.channel.best],['Hazırlık',row.channel.assets.join(' · ')],['Coğrafya araştırma notu',row.channel.geo],['Sınır',row.channel.note]];
  if(state.plan.interactive){pairs[7][1]=`${S.version} · ${row.f.updated} · hazırlanmış dinamik demo; piyasa verisi değil`;pairs[8][1]='Yalnız mevcut demo koşulları için türetilmiş; gerçek hedefleme / hesap onayı sağlamaz.';pairs.push(['Örnek hesap varsayımı',row.f.accountReady?'Bu senaryoda hazır varsayıldı; gerçek bağlantı yok':'Bu senaryoda hazır varsayılmadı']);}
  const dl=el('dl',undefined,'guide-dl');pairs.forEach(([k,v])=>dl.append(el('dt',k),el('dd',v)));root.append(dl);const det=el('details');det.append(el('summary','Puanın 8 boyutunu incele'));row.breakdown.forEach(x=>det.append(el('p',`${x.dimension}: ${x.score}/5 × %${x.weight} = ${x.points} puan`)));root.append(det);
  row.channel.sourceIds.forEach(id=>{const s=D.sources.find(s=>s.id===id);if(!s)return;const p=el('p',`${id} · ${s.title} · ${s.publisher} · araştırma kaynağı; bağımsız kontrol edilmedi`,'hint');if(/^https:\/\//.test(s.url)){const a=el('a','Kaynağı aç');a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';p.append(' ',a);}root.append(p);});$('guide').showModal();}
$('guide-close').addEventListener('click',()=>$('guide').close());
function renderPlan(){const p=state.plan;if(!p)return;const stats=$('plan-summary');stats.replaceChildren();[['Toplam bütçe',money(p.total)],['Önerilen yatırım',money(p.allocated)],['Ayrılmamış bütçe',money(p.unallocated)]].forEach(([t,v])=>{const n=el('div',undefined,'summary-stat');n.append(el('span',t),el('strong',v));stats.append(n);});
  const upper=$('recommended'),lower=$('other-channels');upper.replaceChildren();lower.replaceChildren();
  const groups={};[['paid','Diğer reklam ürünleri'],['managed','Partner / yönetilen satın alma'],['owned','Reklam bütçesi dışındaki aksiyonlar']].forEach(([id,title])=>{const g=el('section',undefined,'catalog-group');g.append(el('h3',title));lower.append(g);groups[id]=g;});
  const ordered=[...p.rows].sort((a,b)=>b.amount-a.amount || b.score-a.score);
  ordered.forEach(r=>{const row=el('article',undefined,r.amount?'channel-row':'other-channel');row.dataset.channel=r.channel.id;const main=el('div',undefined,'channel-main');main.append(el('span',r.channel.family.slice(0,2),'channel-logo'));const info=el('div',undefined,'channel-info');info.append(el('h3',r.channel.name),el('p',r.amount?`${r.score}/100 uygunluk · ${money(r.useful)} test min. · ${money(r.cap)} tavan`:r.reasons.map(x=>E.reasonText[x]).join(' · ')||'Uygun aday; şu an pay ayrılmadı'));main.append(info);row.append(main);
    const controls=el('div',undefined,'channel-allocation');if(r.amount){const input=el('input');input.type='number';input.min='0';input.max=(r.cap/100).toFixed(2);input.step='0.01';input.value=(r.amount/100).toFixed(2);input.setAttribute('aria-label',`${r.channel.name} bütçesi TL`);input.addEventListener('change',()=>{try{E.manual(p,r.channel.id,Math.round(Number(input.value)*100));renderPlan();$('decision-status').textContent='Manuel tutar uygulandı. Yeniden öner düğmesi bu değişikliği sıfırlar.';}catch(err){$('decision-status').textContent=err.message;input.value=(r.amount/100).toFixed(2);}});controls.append(input,el('span',`TL · %${percent(r.amount,p.total)}`));}
    else if(r.eligible){controls.append(btn('Plana ekle',()=>{try{E.manual(p,r.channel.id,r.useful);renderPlan();}catch(err){$('decision-status').textContent=err.message;}},'secondary'));}
    else controls.append(el('span',r.owned?'Bütçe dışı':r.reasons.includes('policy_review')?'İnceleme':'Eksik koşul','status'));
    const book=btn('ⓘ',()=>guide(r),'book-button');book.setAttribute('aria-label',`${r.channel.name} neden ve koşullar`);controls.append(book);row.append(controls);
    if(r.amount){
      const slider=el('input');slider.type='range';slider.min='0';slider.max=String(r.cap);slider.step='1';slider.value=String(r.amount);slider.className='share-slider';slider.setAttribute('aria-label',`${r.channel.name} payını ayarla`);
      slider.addEventListener('change',()=>{try{E.manual(p,r.channel.id,+slider.value);renderPlan();$('decision-status').textContent='Payı değiştirdin. Minimum ve tavan korundu; kalan tutar ayrılmamış bütçede.';}catch(err){$('decision-status').textContent=err.message;slider.value=String(r.amount);}});
      row.append(slider);upper.append(row);
    }else groups[r.owned?'owned':/managed|partner|creator/.test(r.channel.purchase)?'managed':'paid'].append(row);
  });if(!p.allocated)upper.append(el('p',p.blocked?'Bu istekte önce belge / politika incelemesi gerekli. İçerik taslağın korunuyor.':'Bu koşullarda uygulanabilir bir bütçe önerisi yok. Eksik koşulları aşağıdan inceleyebilirsin.','empty-state'));
  $('why-plan').replaceChildren(el('strong','Bu plan neden böyle?'),el('p',p.blocked?'İnceleme kapısı kanal puanından önce gelir; kullanıcı beyanı belge onayı sayılmaz.':p.interactive?`Bu senaryoda ${label('goal').toLocaleLowerCase('tr-TR')} hedefi ve ${label('audience').toLocaleLowerCase('tr-TR')} için hesap / içerik varsayımları değerlendirildi. Bütçe önce anlamlı testlere, sonra puan ve örnek talep tavanlarına göre dağıtıldı. Pay almayana nedenini ⓘ düğmesinden sorabilirsin.`:p.bound?'Kanallara önce anlamlı test tutarı ayrıldı. Kalan tutar uzman puanının karesiyle, talep ve ortak işletme tavanlarına kadar dağıtıldı. Kalan bütçeyi harcamak zorunda değilsin.':'Örnek Kadıköy tahmini başka bölgeye, hedefe, tarihe veya kitleye taşınmadı. Gerçek hesaptan yeni bir tahmin alınmadan kesin rakam gösterilmez.'),el('small',`${D.version} · ${p.interactive?S.version+' · temsili senaryo':'8 boyutlu uzman başlangıç puanları'} · gerçek tahmin ve garanti yok · AI çağrısı yok`));
  if(p.interactive)p.rows.filter(r=>r.amount).forEach(r=>{const traffic=r.f.cpc>0?Math.floor(r.amount/100/r.f.cpc):0,impressions=r.f.cpm>0?Math.floor(r.amount/100/r.f.cpm*1000):null;const text=`TEMSİLİ ÖRNEK · ${impressions?`${Math.floor(impressions*.75).toLocaleString('tr-TR')}–${Math.floor(impressions*1.25).toLocaleString('tr-TR')} gösterim · `:''}${Math.floor(traffic*.7)}–${Math.floor(traffic*1.3)} tıklama; gerçek tahmin değildir.`;upper.querySelector(`[data-channel="${r.channel.id}"]`).append(el('p',text,'simulated-results'));});
}
$('plan-form').addEventListener('submit',e=>{e.preventDefault();if(!state.plan||state.stale){$('decision-status').textContent='Koşullar değişti. Önce dağılımı yeniden öner.';return;}state.unlocked=3;go(3);});
function review(){
  const p=state.plan,c=state.cards.find(c=>c.id===state.selected),root=$('review');root.replaceChildren();if(!p||!c)return;
  const visual=el('div');visual.append(artwork(c));const body=el('section',undefined,'review-panel'),dl=el('dl');
  const pairs=[['İletişim işi',label('communication')],['İstek',state.brief.description],['Kitle',state.brief.audience],['İstenen aksiyon',label('action')],
    ['Yaratıcı rota',`${c.angle} · ${c.tone} · ${c.format} · revizyon ${c.revision}`],['Mesaj / CTA',`${c.title} · ${c.message} · ${c.cta}`],['Reklam hedefi',label('goal')],
    ['Bölge',`${p.input.geo==='nationwide'?'Türkiye':p.input.region}${p.input.geo==='radius_local'?` · ${p.input.radius} km`:''} · hedefleme doğrulanmadı`],
    ['Önerilen bütçe',money(p.allocated)],['Ayrılmamış bütçe',money(p.unallocated)],
    ['Kanal planı',p.rows.filter(r=>r.amount).map(r=>`${r.channel.name}: ${money(r.amount)}`).join(' · ')||'Koşullar bekliyor'],
    ['Veri durumu',p.interactive?'Hazırlanmış dinamik demo · örnek hesaplar ve maliyetler · gerçek tahmin değil':'Tarihli SC01 temsili verisi · gerçek sonuç / getiri garantisi yok'],
    ['Kur kaynağı',`${fxName(p.fx.source)} · ${p.fx.source_as_of} · 1 USD = ${p.fx.rate.toLocaleString('tr-TR',{maximumFractionDigits:8})} TRY · işlem kuru değildir`],
    ['Kur kayıt kimliği',p.fx.snapshot_id||'Canlı kaynak kaydı yok; tarihli örnek'],
    ['Üretim ve hizmet bedeli','Bu prototipte hesaplanmaz; medya bütçesinden ayrıdır'],['Yayın hazırlığı','KAPALI · gerçek hesap, izin, ölçüm ve platform tahminleri bekliyor']];
  pairs.forEach(([k,v])=>dl.append(el('dt',k),el('dd',v)));body.append(dl);root.append(visual,body);$('finish-status').textContent='';$('finish').disabled=false;
}
$('finish').addEventListener('click',()=>{if(state.stale){$('finish-status').textContent='Kaynak veya plan koşulları değişti. Planı yeniden değerlendir.';return;}$('finish-status').textContent='Taslak kontrol edildi. Kalıcı kampanya kaydı, AI çağrısı, ödeme ve reklam yayını yapılmadı.';$('finish').disabled=true;});
function chat(t){const log=$('chat-log');log.append(el('div',t,'user-message'));const intent=S.intent(t),selected=state.cards.find(c=>c.id===state.selected);let answer='',action=null,actionLabel='Öneriyi uygula';
  if(intent.type==='patch'){answer=`Şu değişikliği hazırladım: ${Object.entries(intent.patch).map(([k,v])=>`${({budget:'Bütçe (TL)',duration:'Süre (gün)',region:'Bölge',radius:'Yarıçap (km)','geo-mode':'Konum türü'})[k]}: ${v}`).join(' · ')}. İçeriğin korunacak; uygularsan örnek dağılım yeniden hesaplanacak.`;action=()=>{applyPatch(intent.patch);if(state.step===2)recommend();};}
  else if(intent.type==='simplify'||intent.type==='alternative'){answer=selected?`${selected.angle} yönünü koruyup ${intent.type==='simplify'?'daha kısa ve sade':'aynı tarzda alternatif'} bir metin hazırlayabilirim. Önceki metni Geri al ile geri getirebilirsin.`:'Önce bir içerik yönü seç. Sonra o içeriğe özel değişikliği hazırlayabilirim.';if(selected)action=()=>{selected.edits.push({title:selected.title,message:selected.message,cta:selected.cta,x:selected.x,y:selected.y});Object.assign(selected,S.alternative(selected,state.brief));if(intent.type==='simplify'){selected.message=selected.message.split(';')[0].split('.')[0]+'.';selected.title=selected.title.split('.')[0]+'.';}selected.revision++;invalidate();renderCards();if(state.step===3)go(1);};}
  else if(intent.type==='regenerate'){answer=state.brief?'Aynı istek ve kimlikle üç farklı yön hazırlayacağım. Önceki üçlünü geri getirebilirsin.':'Önce isteğini soldaki alana yaz; ardından üç yönü hazırlayalım.';if(state.brief)action=()=>{makeCards();go(1);};}
  else if(intent.type==='explain'){answer=state.plan?`${state.brief?.identity||'Bu çalışma'} için ${money(state.plan.allocated)} önerildi, ${money(state.plan.unallocated)} ayrılmadı. ${state.plan.rows.filter(r=>r.amount).map(r=>`${r.channel.name}: ${money(r.amount)}, tavanı ${money(r.cap)}`).join(' · ')}. ${state.stale?'Koşullar değişti; eski sonuç güncel değil. ':''}Bu tutarlar hazırlanmış demo varsayımlarıdır. Önce koşullar, sonra test minimumu, puan ve tavanlar uygulanır.`:'İçeriği seçtikten sonra hedef, bölge ve bütçene göre kanal gerekçelerini birlikte göreceğiz. İstersen bütçe 5000, 14 gün gibi bir değişiklik yazabilirsin.';}
  else if(intent.type==='policy'){answer='İçerik fikrini taslak olarak koruyabiliriz. Gerekli belge / politika kontrolü tamamlanmadan ücretli öneri açılmaz. Bu demoda bir mesaj veya kutucuk belge doğrulaması yerine geçmez.';}
  else if(intent.type==='brief'){answer=`Bunu ${intent.profile.name.toLocaleLowerCase('tr-TR')} çalışması olarak ele alabilirim. Mesajını istek alanına, ilgili seçimleri örnek profile yerleştireceğim. Sonra seçenekleri kontrol edip içerik aşamasına geçebilirsin.`;action=()=>{loadExample(intent.profile,t);go(0);};actionLabel='İsteğime yerleştir';}
  else {answer=[`Kısa anlatımın hazır. Şimdi “${label('communication')}” seçimini ve istediğin aksiyonu kontrol edip üç yaratıcı yönü açabilirsin.`,`Şu anda ${state.selected?'bir yön seçtin':'üç farklı yönün var'}. “Daha sade olsun”, “benzerini üret” veya “yeni üçlü” yazabilirsin.`,`Şu an ${label('goal').toLocaleLowerCase('tr-TR')} için ${$('region').value} planındayız. Örneğin “bütçe 5000, 14 gün” yaz; uygulamadan önce değişikliği göstereyim.`,`İçeriğin ve planın bir arada. Taslağı tamamlayabilir veya planına geri dönebilirsin; gerçek reklam yayını açılmaz.`][state.step];}
  const message=el('div',answer,'assistant-message');if(action){const proposalContext=assistantContext();const apply=btn(actionLabel,()=>{if(proposalContext!==assistantContext()){apply.disabled=true;apply.textContent='Koşullar değişti · Yeniden iste';return;}action();apply.disabled=true;apply.textContent='✓ Uygulandı';},'secondary');message.append(apply);}message.append(el('small','Hazırlanmış yerel demo yanıtı · canlı AI değildir'));log.append(message);while(log.children.length>24)log.firstElementChild.remove();log.scrollTop=log.scrollHeight;
}
function assistantContext(){return JSON.stringify({step:state.step,brief:briefObject(),selected:state.selected,cards:state.cards.map(c=>[c.id,c.revision]),inputs:inputs(),revision:state.revision,amounts:state.plan?.rows.map(r=>[r.channel.id,r.amount])});}
$('chat-form').addEventListener('submit',e=>{e.preventDefault();const t=$('chat-input').value.trim();if(t)chat(t);$('chat-input').value='';});
$('helper-toggle').addEventListener('click',()=>{const open=$('helper-panel').classList.toggle('mobile-open');$('helper-toggle').setAttribute('aria-expanded',String(open));if(open)$('chat-input').focus();});
window.YaparoStudio = {getSnapshot:()=>structuredClone({brief:state.brief,creative:state.cards.find(c=>c.id===state.selected),plan:state.plan,stale:state.stale,revision:state.revision})};
// Keep campaign conditions and their consequences side by side, not in a long column.
const planForm=$('plan-form'), planControls=el('div'), planResults=el('div');planControls.id='plan-controls';planResults.id='plan-results';
let resultSection=false;[...planForm.children].forEach(node=>{if(node.classList.contains('form-footer'))return;if(node.classList.contains('decision-toolbar'))resultSection=true;(resultSection?planResults:planControls).append(node);});planForm.prepend(planControls,planResults);
['order-value','margin','cpa','capacity'].forEach(id=>$(id).required=true);
$('goal').addEventListener('change',()=>state.goalManual=true);
function applyPatch(patch){for(const [id,value] of Object.entries(patch)){if($(id))$(id).value=value;}geoVisibility();invalidate();}
function restoreBrief(b){if(!b)return;for(const [id,key] of [['communication','communication'],['business','business'],['action','action'],['brief','description'],['audience-description','audience'],['sector','sector'],['risk','risk'],['identity','identity'],['message','message']])$(id).value=b[key]||'';state.answers={...b.branch};state.briefDirty=false;branches();}
function loadExample(p,description){state.goalManual=false;const isB2B=p===S.profiles.saas;const examples={coffee:'Sentetik örnek: İzmir’deki Örnek Kafe’de taze hazırladığımız kahveleri tanıtmak, yakındaki kişileri hafta sonu bir molaya davet etmek istiyorum.',fashion:'Sentetik örnek: Kadıköy’deki Örnek Butik’in özgün tasarımlarını tanıtmak ve insanları koleksiyonu mağazada görmeye davet etmek istiyorum.',software:'Sentetik örnek: Örnek Yazılım, küçük ekiplerin görevlerini tek yerde takip ettiği bir araç. İşletme sahiplerinden ürün tanışması için form talebi toplamak istiyorum.',home:'Sentetik örnek: Ankara’daki Örnek Ev Hizmeti için çalışma bölgemdeki insanlara bakım hizmetimizi anlatmak, önce telefonla ihtiyaçlarını öğrenmek istiyorum.',event:'Sentetik örnek: İzmir’de yetişkinlere yönelik bir seramik atölyesi düzenliyoruz. Etkinlik tarihini daha sonra belirleyip katılım bilgisi isteyenleri başvuruya yönlendirmek istiyorum.'};
  $('communication').value=p.communication||'product_service_intro';$('business').value=p.business;$('action').value=p.action;$('sector').value=p.sector;$('audience').value=p.audience;$('goal').value=p.goal;$('risk').value='normal';$('brief').value=description||examples[p.theme]||'Sentetik örnek: Yeni fikrimi tanıtmak, ilgilenen kişileri daha fazla bilgi almaya davet etmek istiyorum.';$('audience-description').value=isB2B?'Küçük ve orta ölçekli ekiplerin karar vericileri':'Bölgedeki ilgili yetişkinler';$('identity').value=({coffee:'Örnek Kafe',fashion:'Örnek Butik',software:'Örnek Yazılım',home:'Örnek Ev Hizmeti',event:'Örnek Atölye'})[p.theme]||'Örnek Çalışma';$('message').value='';state.answers={};$('fixture').value='interactive';$('demo-readiness').value='core';$('geo-mode').value=isB2B?'country':'area';$('region').value=p.theme==='home'?'Ankara':p.theme==='fashion'?'İstanbul, Kadıköy':'İzmir';$('budget').value=isB2B?'20000':'3000';$('order-value').value=isB2B?'10000':'500';$('margin').value=isB2B?'60':'40';$('cpa').value=isB2B?'600':'100';$('capacity').value=isB2B?'10':'20';$('duration').value='7';$('video').checked=false;$('catalog').checked=false;$('tracking').checked=false;branches();geoVisibility();briefChanged();}
for(const [key,text] of [['cafe','☕ Kafe açılışı'],['fashion','◈ Butik koleksiyonu'],['saas','▤ B2B yazılım'],['home','⌂ Yerel hizmet'],['event','✦ Atölye daveti']])$('scenario-examples').append(btn(text,()=>loadExample(S.profiles[key]),'scenario-chip'));
const suggestions=el('div',undefined,'helper-suggestions');for(const text of ['Daha sade olsun','Bütçe 5000, 14 gün','Neden bu kanallar?'])suggestions.append(btn(text,()=>chat(text),'scenario-chip'));$('chat-form').before(suggestions);
function sourceContext(){const creative=state.cards.find(c=>c.id===state.selected);return {...inputs(),creative_id:creative?.id||'unselected',creative_revision:creative?.revision||1,rule_version:D.version};}
window.YaparoSources.configure({mount:$('plan-controls'),readContext:sourceContext,readChannels:()=>state.plan?.rows.filter(r=>r.amount&&!r.owned).map(r=>r.channel.id)||[],channelName:id=>D.channels.find(c=>c.id===id)?.name||id,onChange:()=>{if(state.plan){invalidate();$('decision-status').textContent='Veri kaynağının durumu değişti. Güncel kaynaklarla dağılımı yeniden öner.';}}});
